import{_ as e,o,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-11-11 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-11-11 :: Ceph Orchestration Meeting","date":"2019-11-11T00:00:00.000Z","updated":"2019-11-12T00:00:00.000Z","tags":["Ceph","分布式存储","Rook项目","Orchestrator","社区讨论"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-11_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-11-11_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),l={name:"posts/2019/2019-11-11_-_-_Ceph_Orchestration_Meeting.md"};function s(a,t,n,p,h,_){return o(),r("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Miguel、Sebastian、Paige、Mike Latimer、其他未提及的参与者</p><p><strong>会议主题</strong>： Ceph社区讨论、Rook项目进展、Orchestrator相关讨论</p><p><strong>关键细节</strong>：</p><ul><li><p><strong>Ceph社区讨论</strong>：</p><ul><li>上周在Epic City的CDM会议中，进行了关于Ceph的积极讨论。</li><li>讨论了从Orchestrator视角添加新功能的可能性，但具体细节未透露。</li><li>提出了关于Rook和升级相关的问题，需要与State团队讨论。</li><li>容器镜像名称变化是否足以进行升级，以及Rook是否依赖于不同的镜像名称或标签。</li><li>讨论了不使用“latest”版本的原因。</li></ul></li><li><p><strong>Rook项目进展</strong>：</p><ul><li>SEF（Staff Volume Inventory）已合并至上周的版本中。</li><li>Client Python作为依赖项，已讨论在Rook仓库中引入Python客户端库。</li><li>Sebastian将更新现有PR或创建新PR以实现此功能。</li></ul></li><li><p><strong>Orchestrator相关讨论</strong>：</p><ul><li>Orchestrator方面正在积极进行代码开发。</li><li>有多个团队参与Elaste orchestrated effort，以及大量的PF（Performance Fix）。</li><li>大新闻是DeepSea Orchestrator的开发工作可能即将停止，团队将更加专注于Cosmo和Rook两个Orchestrator。</li><li>Daniel（来自Red Hat的新成员）正在研究Antilochus Twitter。</li><li>讨论了关于Hedgehog Twitter的决策，决定停止该项目。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>Sebastian将更新现有PR或创建新PR以将Python客户端库引入Rook仓库。</li><li>团队将专注于Cosmo和Rook两个Orchestrator，DeepSea Orchestrator的开发工作可能即将停止。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Sebastian将更新现有PR或创建新PR。</li><li>团队将继续专注于Cosmo和Rook两个Orchestrator的开发。</li><li>Daniel将继续研究Antilochus Twitter。</li></ul><p><strong>改进点</strong>：</p><ul><li>确保了会议纪要的要点准确反映了原始内容。</li><li>包括了所有关键细节，如Ceph社区讨论的细节、Rook项目进展和Orchestrator相关讨论。</li><li>明确了决定的事项和后续行动计划。</li><li>在总结中保留了所有相关的Ceph相关关键词。</li></ul>',12)])])}const u=e(l,[["render",s]]);export{g as __pageData,u as default};
